// Some portions generated by Claude
/** The DOM tooltip of the large-graph canvas: what it says and where it goes (the canvas itself draws no titles). */
import type { GraphNode } from "./graph-types.ts";
import { termTooltip } from "./graph-terms.ts";

/** The label, and under it the full IRI (or _:id); a literal has only its value. */
export function largeGraphTooltip(node: Pick<GraphNode, "id" | "label" | "kind">) {
  return { title: node.label, detail: node.kind === "literal" ? "" : termTooltip(node.id) };
}

const OFFSET_X = 12;
const OFFSET_Y = 14;

/** Beside the pointer, flipped to the other side near the stage's right or bottom edge, and always inside it. */
export function tooltipPlacement(
  pointer: { x: number; y: number },
  stage: { left: number; top: number; width: number; height: number },
  size: { width: number; height: number },
) {
  const x = pointer.x - stage.left;
  const y = pointer.y - stage.top;
  let left = x + OFFSET_X;
  let top = y + OFFSET_Y;
  if (left + size.width > stage.width) left = x - OFFSET_X - size.width;
  if (top + size.height > stage.height) top = y - OFFSET_Y - size.height;
  return {
    left: Math.max(0, Math.min(left, stage.width - size.width)),
    top: Math.max(0, Math.min(top, stage.height - size.height)),
  };
}
